import sys

def main():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    Q = int(next(it))

    L = [0] * (M + 1)
    R = [0] * (M + 1)
    D = [0] * (M + 1)  # direction: +1 right, -1 left

    for i in range(1, M + 1):
        s = int(next(it))
        t = int(next(it))
        a = min(s, t) - 1
        b = max(s, t) - 1
        L[i] = a
        R[i] = b
        D[i] = 1 if s < t else -1

    g = [0] * (M + 1)

    # 1. same L, different R
    L_map = {}
    for i in range(1, M + 1):
        l = L[i]
        r = R[i]
        if l in L_map:
            last_idx, last_R, alt_idx = L_map[l]
            if last_R != r:
                cand = last_idx
            else:
                cand = alt_idx
            if cand > g[i]:
                g[i] = cand
            new_alt = last_idx if last_R != r else alt_idx
            L_map[l] = (i, r, new_alt)
        else:
            L_map[l] = (i, r, 0)

    # 2. same R, different L
    R_map = {}
    for i in range(1, M + 1):
        l = L[i]
        r = R[i]
        if r in R_map:
            last_idx, last_L, alt_idx = R_map[r]
            if last_L != l:
                cand = last_idx
            else:
                cand = alt_idx
            if cand > g[i]:
                g[i] = cand
            new_alt = last_idx if last_L != l else alt_idx
            R_map[r] = (i, l, new_alt)
        else:
            R_map[r] = (i, l, 0)

    # 3. same L,R, opposite direction
    LR_map = {}
    for i in range(1, M + 1):
        key = (L[i], R[i])
        if key in LR_map:
            last_idx, last_dir = LR_map[key]
            if last_dir != D[i]:
                if last_idx > g[i]:
                    g[i] = last_idx
        LR_map[key] = (i, D[i])

    # Segment tree for crossing (point update, range max)
    class SegTree:
        __slots__ = ('N', 'data')
        def __init__(self, n):
            N = 1
            while N < n:
                N <<= 1
            self.N = N
            self.data = [0] * (2 * N)
        def update(self, pos, val):
            i = pos + self.N
            if self.data[i] >= val:
                return
            self.data[i] = val
            i >>= 1
            while i:
                new = self.data[2 * i]
                if self.data[2 * i + 1] > new:
                    new = self.data[2 * i + 1]
                self.data[i] = new
                i >>= 1
        def query(self, l, r):
            if l > r:
                return 0
            l += self.N
            r += self.N
            res = 0
            while l <= r:
                if l & 1:
                    if self.data[l] > res:
                        res = self.data[l]
                    l += 1
                if not (r & 1):
                    if self.data[r] > res:
                        res = self.data[r]
                    r -= 1
                l >>= 1
                r >>= 1
            return res
        def reset(self, pos):
            i = pos + self.N
            self.data[i] = 0
            i >>= 1
            while i:
                new = self.data[2 * i]
                if self.data[2 * i + 1] > new:
                    new = self.data[2 * i + 1]
                self.data[i] = new
                i >>= 1

    seg = SegTree(N)  # coordinates 0..N-1

    sys.setrecursionlimit(1 << 25)

    def cdq(arr, l, r):
        if l >= r:
            return
        mid = (l + r) // 2
        cdq(arr, l, mid)
        cdq(arr, mid + 1, r)
        left = arr[l:mid + 1]
        right = arr[mid + 1:r + 1]

        # Pattern 1: L_i < L_j < R_i < R_j
        left1 = sorted(left, key=lambda x: L[x])
        right1 = sorted(right, key=lambda x: L[x])
        p = 0
        updated = []
        for j in right1:
            while p < len(left1) and L[left1[p]] < L[j]:
                idx = left1[p]
                seg.update(R[idx], idx)
                updated.append(R[idx])
                p += 1
            if L[j] + 1 <= R[j] - 1:
                val = seg.query(L[j] + 1, R[j] - 1)
                if val > g[j]:
                    g[j] = val
        for pos in updated:
            seg.reset(pos)

        # Pattern 2: L_j < L_i < R_j < R_i
        left2 = sorted(left, key=lambda x: R[x], reverse=True)
        right2 = sorted(right, key=lambda x: R[x], reverse=True)
        p = 0
        updated = []
        for j in right2:
            while p < len(left2) and R[left2[p]] > R[j]:
                idx = left2[p]
                seg.update(L[idx], idx)
                updated.append(L[idx])
                p += 1
            if L[j] + 1 <= R[j] - 1:
                val = seg.query(L[j] + 1, R[j] - 1)
                if val > g[j]:
                    g[j] = val
        for pos in updated:
            seg.reset(pos)

    right_idx = [i for i in range(1, M + 1) if D[i] == 1]
    left_idx = [i for i in range(1, M + 1) if D[i] == -1]
    if right_idx:
        cdq(right_idx, 0, len(right_idx) - 1)
    if left_idx:
        cdq(left_idx, 0, len(left_idx) - 1)

    # Build segment tree for g to answer range max queries
    class SegTreeMax:
        __slots__ = ('N', 'data')
        def __init__(self, n):
            N = 1
            while N < n:
                N <<= 1
            self.N = N
            self.data = [0] * (2 * N)
        def build(self, arr):
            # arr is 1-indexed, length M+1
            for i in range(1, len(arr)):
                self.data[self.N + i - 1] = arr[i]
            for i in range(self.N - 1, 0, -1):
                self.data[i] = self.data[2 * i] if self.data[2 * i] > self.data[2 * i + 1] else self.data[2 * i + 1]
        def query(self, l, r):
            # l, r are 0-indexed inclusive
            l += self.N
            r += self.N
            res = 0
            while l <= r:
                if l & 1:
                    if self.data[l] > res:
                        res = self.data[l]
                    l += 1
                if not (r & 1):
                    if self.data[r] > res:
                        res = self.data[r]
                    r -= 1
                l >>= 1
                r >>= 1
            return res

    seg_g = SegTreeMax(M)
    seg_g.build(g)

    out = []
    for _ in range(Q):
        l = int(next(it))
        r = int(next(it))
        ans = seg_g.query(l - 1, r - 1)
        out.append("Yes" if ans < l else "No")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

