class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        max_val = max(nums) if nums else 0
        max_sum = n * max_val                     # maximal absolute alternating sum
        if abs(k) > max_sum:                      # impossible to reach k
            return -1

        offset = max_sum
        size = 2 * max_sum + 1                     # indices for sums -max_sum … max_sum
        sentinel = limit + 1                       # value meaning "product > limit"

        # dp[sum_idx][par] = maximum product reachable for this sum and parity
        # par = 0 -> even length, par = 1 -> odd length
        # -1 means unreachable; sentinel means product > limit (still reachable but cannot be used for a valid final product)
        dp = [[-1, -1] for _ in range(size)]

        for v in nums:
            # copy current table – we will add transitions that use the current v
            ndp = [row[:] for row in dp]

            # ---- start a new subsequence with v (first element) ----
            idx = v + offset
            old_start = ndp[idx][1]
            if v <= limit:
                # valid product: replace sentinel or keep larger product
                if old_start == -1 or old_start == sentinel or v > old_start:
                    ndp[idx][1] = v
            else:
                # product exceeds limit: store sentinel only if cell is empty
                if old_start == -1:
                    ndp[idx][1] = sentinel

            # ---- extend already existing subsequences ----
            for s_idx in range(size):
                s_val = s_idx - offset
                for par in (0, 1):
                    cur = dp[s_idx][par]
                    if cur == -1:
                        continue
                    # sign of the next element
                    sign = 1 if par == 0 else -1
                    new_sum = s_val + sign * v
                    if new_sum < -max_sum or new_sum > max_sum:
                        continue
                    new_idx = new_sum + offset
                    new_par = par ^ 1

                    # compute new product
                    if v == 0:
                        new_prod = 0
                    else:
                        if cur > limit:
                            new_prod = sentinel
                        else:
                            prod = cur * v
                            if prod > limit:
                                new_prod = sentinel
                            else:
                                new_prod = prod

                    # update the table – valid products must replace sentinel
                    old_ext = ndp[new_idx][new_par]
                    if new_prod <= limit:
                        # valid product: replace sentinel or keep larger product
                        if old_ext == -1 or old_ext == sentinel or new_prod > old_ext:
                            ndp[new_idx][new_par] = new_prod
                    else:
                        # product exceeds limit (sentinel): store only if cell empty
                        if old_ext == -1:
                            ndp[new_idx][new_par] = sentinel

            dp = ndp

        target = k + offset
        ans = -1
        for par in (0, 1):
            val = dp[target][par]
            if val != -1 and val <= limit:
                if val > ans:
                    ans = val
        return ans

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(n: int) -> int:
            if n <= 0:
                return 0
            s = str(n)
            digits = [int(c) for c in s]
            L = len(digits)
            # precompute powers of 10
            pow10 = [1] * (L + 1)
            for i in range(1, L + 1):
                pow10[i] = pow10[i - 1] * 10

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def free(pos: int, s_sum: int, s_prod: int, started: bool) -> int:
                """Count beautiful numbers for the suffix starting at pos,
                assuming no tight constraint (any digits 0-9 are allowed)."""
                if pos == L:
                    if not started:
                        return 0  # number 0 is not counted
                    if s_prod == 0:
                        return 1
                    return 1 if s_prod % s_sum == 0 else 0
                if s_prod == 0:
                    # once a zero appears, the number is beautiful for any continuation
                    return pow10[L - pos]
                total = 0
                for d in range(10):
                    if not started and d == 0:
                        # still in the "not started" state
                        total += free(pos + 1, 0, 1, False)
                    else:
                        new_started = True
                        new_sum = s_sum + d
                        new_prod = s_prod * d
                        total += free(pos + 1, new_sum, new_prod, new_started)
                return total

            @lru_cache(maxsize=None)
            def f(pos: int, s_sum: int, s_prod: int, started: bool, tight: bool) -> int:
                """Digit DP with tight constraint."""
                if pos == L:
                    if not started:
                        return 0
                    if s_prod == 0:
                        return 1
                    return 1 if s_prod % s_sum == 0 else 0
                limit = digits[pos] if tight else 9
                total = 0
                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    if not started and d == 0:
                        # still not started
                        if new_tight:
                            total += f(pos + 1, 0, 1, False, True)
                        else:
                            total += free(pos + 1, 0, 1, False)
                    else:
                        new_started = True
                        new_sum = s_sum + d
                        new_prod = s_prod * d
                        if new_tight:
                            total += f(pos + 1, new_sum, new_prod, True, True)
                        else:
                            total += free(pos + 1, new_sum, new_prod, True)
                return total

            return f(0, 0, 1, False, True)

        return count(r) - count(l - 1)

import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    K = int(next(it))
    # Special case: K = 1, every vertex is a path of length 1.
    if K == 1:
        print("Yes")
        return
    total = N * K
    adj = [[] for _ in range(total + 1)]
    for _ in range(total - 1):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    # Compute parent and depth using iterative DFS (root at 1).
    parent = [0] * (total + 1)
    depth = [0] * (total + 1)
    stack = [1]
    parent[1] = 0
    depth[1] = 0
    while stack:
        node = stack.pop()
        for nb in adj[node]:
            if nb != parent[node]:
                parent[nb] = node
                depth[nb] = depth[node] + 1
                stack.append(nb)

    # Process nodes in decreasing depth (post‑order).
    nodes = list(range(1, total + 1))
    nodes.sort(key=lambda x: depth[x], reverse=True)
    res = [0] * (total + 1)          # -1 means subtree fully covered, positive = open path length
    possible = True

    for node in nodes:
        open_lengths = []
        for nb in adj[node]:
            if nb == parent[node]:
                continue
            val = res[nb]
            if val != -1:             # an incomplete path from the child
                open_lengths.append(val)
        cnt = len(open_lengths)

        if node == 1:                # root
            if cnt == 0:
                possible = False
                break
            elif cnt == 1:
                if open_lengths[0] == K - 1:
                    res[node] = -1
                else:
                    possible = False
                    break
            elif cnt == 2:
                if open_lengths[0] + open_lengths[1] == K - 1:
                    res[node] = -1
                else:
                    possible = False
                    break
            else:                     # more than two open paths
                possible = False
                break
        else:                         # non‑root
            if cnt == 0:
                res[node] = 1
            elif cnt == 1:
                L = open_lengths[0]
                if L + 1 == K:
                    res[node] = -1
                else:
                    res[node] = L + 1
            elif cnt == 2:
                L1, L2 = open_lengths
                if L1 + L2 == K - 1:
                    res[node] = -1
                else:
                    possible = False
                    break
            else:                     # more than two open paths
                possible = False
                break

    if possible:
        print("Yes")
    else:
        print("No")

