class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        INF = 10**18

        # Pre-compute factorials capped at INF
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(fact[i-1] * i, INF)

        def falling_factorial(a, b):
            # Computes a * (a-1) * ... * (a-b+1) = a! / (a-b)!
            # Capped at INF. Returns 0 if b > a.
            if b > a:
                return 0
            res = 1
            for i in range(b):
                res = min(res * (a - i), INF)
            return res

        used = [False] * (n + 1)
        result = []
        remaining_odds = (n + 1) // 2
        remaining_evens = n // 2

        for pos in range(n):
            if pos == 0:
                required_parity = None
            else:
                # 0 for even, 1 for odd
                required_parity = 1 - (result[-1] % 2)

            found = False
            for num in range(1, n + 1):
                if used[num]:
                    continue
                if required_parity is not None and num % 2 != required_parity:
                    continue

                new_ro = remaining_odds - (1 if num % 2 == 1 else 0)
                new_re = remaining_evens - (1 if num % 2 == 0 else 0)
                remaining_len = n - pos - 1

                if remaining_len == 0:
                    count = 1
                else:
                    # Next required parity is opposite of current num's parity
                    next_parity = 1 - (num % 2)
                    if next_parity == 1:  # odd
                        odd_needed = (remaining_len + 1) // 2
                    else:
                        odd_needed = remaining_len // 2
                    even_needed = remaining_len - odd_needed

                    if new_ro < odd_needed or new_re < even_needed:
                        count = 0
                    else:
                        c1 = falling_factorial(new_ro, odd_needed)
                        c2 = falling_factorial(new_re, even_needed)
                        count = min(c1 * c2, INF)

                if k > count:
                    k -= count
                else:
                    result.append(num)
                    used[num] = True
                    remaining_odds = new_ro
                    remaining_evens = new_re
                    found = True
                    break

            if not found:
                return []

        return result

