class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        L = 4 * side  # total perimeter length

        # Map each point to its position on the perimeter (clockwise from (0,0))
        pos = []
        for x, y in points:
            if y == 0:          # bottom edge: (x,0)
                p = x
            elif x == side:     # right edge: (side,y)
                p = side + y
            elif y == side:     # top edge: (x,side)
                p = 2 * side + (side - x)
            else:               # left edge: (0,y), x == 0
                p = 3 * side + (side - y)
            pos.append(p)
        pos.sort()
        n = len(pos)

        # Decision function: can we pick k points with pairwise distance >= d ?
        def feasible(d: int) -> bool:
            if d * k > L:
                return False

            # Extended array: original + shifted by L to handle wrap-around
            pos2 = pos + [p + L for p in pos]
            n2 = 2 * n

            # Pre-compute nxt[i]: first index j > i with pos2[j] - pos2[i] >= d
            # and j - i < n (still within the same circle)
            nxt = [-1] * n2
            j = 0
            for i in range(n2):
                if j < i + 1:
                    j = i + 1
                while j < n2 and j - i < n and pos2[j] - pos2[i] < d:
                    j += 1
                if j < n2 and j - i < n:
                    nxt[i] = j
                else:
                    nxt[i] = -1

            # Try every possible start point (only the original n points)
            for start in range(n):
                cur = start
                ok = True
                for _ in range(k - 1):
                    nxt_cur = nxt[cur]
                    if nxt_cur == -1 or nxt_cur - start >= n:
                        ok = False
                        break
                    cur = nxt_cur
                if not ok:
                    continue
                # Check the wrap-around distance from last point back to start
                if (pos2[start] + L) - pos2[cur] >= d:
                    return True
            return False

        # Binary search on the answer
        low, high = 0, L // k
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1
        return low

