class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # split p into A * B * C
        i1 = p.find('*')
        i2 = p.find('*', i1 + 1)
        A = p[:i1]
        B = p[i1 + 1:i2]
        C = p[i2 + 1:]
        a, b, c = len(A), len(B), len(C)

        # empty pattern "**"
        if a == 0 and b == 0 and c == 0:
            return 0

        # ---------- KMP: find all occurrences ----------
        def kmp_occurrences(text: str, pat: str):
            """return list of start indices where pat occurs in text"""
            n, m = len(text), len(pat)
            if m == 0:
                return []          # never called for empty pattern
            # prefix function
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j
            # search
            res = []
            j = 0
            for i in range(n):
                while j > 0 and text[i] != pat[j]:
                    j = pi[j - 1]
                if text[i] == pat[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = pi[j - 1]
            return res

        # occurrence lists (None for empty parts)
        occ_A = kmp_occurrences(s, A) if a else None
        occ_B = kmp_occurrences(s, B) if b else None
        occ_C = kmp_occurrences(s, C) if c else None

        # ---------- case B is empty (pattern A**C) ----------
        if b == 0:
            # all three empty
            if a == 0 and c == 0:
                return 0
            # only C needed
            if a == 0:
                return c if occ_C else -1
            # only A needed
            if c == 0:
                return a if occ_A else -1
            # both A and C needed
            if not occ_A or not occ_C:
                return -1
            best = float('inf')
            for a_start in occ_A:
                # first C that does not overlap A
                idx = bisect_left(occ_C, a_start + a)
                if idx < len(occ_C):
                    cur = occ_C[idx] + c - a_start
                    if cur < best:
                        best = cur
            return best if best != float('inf') else -1

        # ---------- B is non‑empty ----------
        if not occ_B:            # B never appears → impossible
            return -1

        best = float('inf')
        for j in occ_B:
            # ----- best possible start of A -----
            if a:
                target_i = j - a
                if target_i < 0:
                    continue
                pos = bisect_right(occ_A, target_i) - 1
                if pos < 0:
                    continue
                i_max = occ_A[pos]
            else:
                i_max = j                     # A empty, start at j

            # ----- best possible start of C -----
            if c:
                target_k = j + b
                pos = bisect_left(occ_C, target_k)
                if pos >= len(occ_C):
                    continue
                k_min = occ_C[pos]
            else:
                k_min = j + b                 # C empty, start right after B

            cur = (k_min + c) - i_max
            if cur < best:
                best = cur

        return best if best != float('inf') else -1

