def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    A = list(map(int, data[1:1 + N]))

    # Count how many A_i are even
    e = sum(1 for a in A if a % 2 == 0)

    if N == 1:
        winner = "Fennec"
    elif N == 2:
        winner = "Snuke"
    else:
        if N % 2 == 1:          # N is odd (N >= 3)
            # Fennec wins if there is at least one odd A_i
            if e < N:            # not all even
                winner = "Fennec"
            else:
                winner = "Snuke"
        else:                   # N is even (N >= 4)
            # Fennec wins if the number of even A_i is odd
            if e % 2 == 1:
                winner = "Fennec"
            else:
                winner = "Snuke"

    sys.stdout.write(winner)

