    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N - 1)]

    # smallest prime factor up to 1000
    MAX_A = 1000
    spf = list(range(MAX_A + 1))
    for i in range(2, MAX_A + 1):
        if spf[i] == i:
            step = i
            start = i * i
            for j in range(start, MAX_A + 1, step):
                if spf[j] == j:
                    spf[j] = i

    # for each prime, list of exponents v_p(A_i)
    prime_alphas = {}
    for idx, a in enumerate(A):
        x = a
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            if p not in prime_alphas:
                prime_alphas[p] = [0] * (N - 1)
            prime_alphas[p][idx] = cnt

    answer = 1
    for p, alphas in prime_alphas.items():
        max_x = sum(alphas)
        if max_x == 0:
            continue  # contribution is 1

        # precompute p^k for k in [-max_x, max_x]
        offset = max_x
        size = 2 * max_x + 1
        pow_p = [1] * size
        for i in range(1, max_x + 1):
            pow_p[offset + i] = pow_p[offset + i - 1] * p % MOD
        inv_p = pow(p, MOD - 2, MOD)
        for i in range(1, max_x + 1):
            pow_p[offset - i] = pow_p[offset - i + 1] * inv_p % MOD

        dp = {(0, 0): 1}
        for alpha in alphas:
            new_dp = defaultdict(int)
            if alpha == 0:
                for (s, m), val in dp.items():
                    pow_s = pow_p[offset + s]
                    key = (s, m)
                    new_dp[key] = (new_dp[key] + val * pow_s) % MOD
            else:
                for (s, m), val in dp.items():
                    # +alpha
                    s1 = s + alpha
                    pow_s1 = pow_p[offset + s1]
                    if s1 >= m:
                        new_dp[(s1, m)] = (new_dp[(s1, m)] + val * pow_s1) % MOD
                    else:
                        new_dp[(s1, s1)] = (new_dp[(s1, s1)] + val * pow_s1) % MOD
                    # -alpha
                    s2 = s - alpha
                    pow_s2 = pow_p[offset + s2]
                    if s2 >= m:
                        new_dp[(s2, m)] = (new_dp[(s2, m)] + val * pow_s2) % MOD
                    else:
                        new_dp[(s2, s2)] = (new_dp[(s2, s2)] + val * pow_s2) % MOD
            dp = new_dp

        # lambda = p^{-N}
        lam = pow(p, MOD - 1 - N, MOD)
        pow_lam_pos = [1] * (max_x + 1)
        for i in range(1, max_x + 1):
            pow_lam_pos[i] = pow_lam_pos[i - 1] * lam % MOD
        inv_lam = pow(lam, MOD - 2, MOD)
        pow_lam_neg = [1] * (max_x + 1)
        for i in range(1, max_x + 1):
            pow_lam_neg[i] = pow_lam_neg[i - 1] * inv_lam % MOD

        Fp = 0
        for (s, m), val in dp.items():
            if m >= 0:
                lam_pow = pow_lam_pos[m]
            else:
                lam_pow = pow_lam_neg[-m]
            Fp = (Fp + val * lam_pow) % MOD
        answer = answer * Fp % MOD

    print(answer)

