import sys

MOD = 998244353

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    M = int(data[1])
    S = data[2].strip()
    # Convert S to list of integer indices 0..25
    s_idx = [ord(ch) - 97 for ch in S]

    size = 1 << N  # number of DP states (bitmask of length N)

    # Precompute transition table: trans[mask][c] = new mask after processing character c
    trans = [[0] * 26 for _ in range(size)]

    for mask in range(size):
        # Reconstruct old DP array (length N+1) from mask
        # old_dp[i] = LCS length of S[0:i] and processed prefix of T
        old_dp = [0] * (N + 1)
        for i in range(1, N + 1):
            # bit i-1 set means dp increased at position i
            old_dp[i] = old_dp[i - 1] + ((mask >> (i - 1)) & 1)

        for c in range(26):
            new_dp = [0] * (N + 1)
            # new_dp[0] = 0
            for i in range(1, N + 1):
                if s_idx[i - 1] == c:
                    # we can extend a subsequence ending at i-1
                    cand = new_dp[i - 1] + 1
                    if old_dp[i] > cand:
                        new_dp[i] = old_dp[i]
                    else:
                        new_dp[i] = cand
                else:
                    # we cannot use the new character at this position
                    if old_dp[i] > new_dp[i - 1]:
                        new_dp[i] = old_dp[i]
                    else:
                        new_dp[i] = new_dp[i - 1]
            # Convert new_dp back to mask
            new_mask = 0
            for i in range(1, N + 1):
                if new_dp[i] == new_dp[i - 1] + 1:
                    new_mask |= (1 << (i - 1))
            trans[mask][c] = new_mask

    # DP over the length of T
    dp = [0] * size
    dp[0] = 1  # empty prefix leads to mask 0

    for _ in range(M):
        ndp = [0] * size
        for mask in range(size):
            cur = dp[mask]
            if cur == 0:
                continue
            row = trans[mask]
            for c in range(26):
                nxt = row[c]
                ndp[nxt] = (ndp[nxt] + cur) % MOD
        dp = ndp

    # Precompute popcount for all masks
    popcnt = [0] * size
    for i in range(1, size):
        popcnt[i] = popcnt[i >> 1] + (i & 1)

    # Aggregate results
    ans = [0] * (N + 1)
    for mask in range(size):
        k = popcnt[mask]
        ans[k] = (ans[k] + dp[mask]) % MOD

    print(' '.join(str(x) for x in ans))

