import sys
from collections import defaultdict

def solve():
    N, P = map(int, sys.stdin.read().split())
    half = N // 2
    max_deg = N * (N - 1) // 2
    poly_len = max_deg + 1

    # Precompute binomial coefficients up to max_deg
    binom = [[0] * (max_deg + 1) for _ in range(max_deg + 1)]
    binom[0][0] = 1
    for n in range(1, max_deg + 1):
        binom[n][0] = binom[n][n] = 1
        for k in range(1, n):
            binom[n][k] = (binom[n-1][k-1] + binom[n-1][k]) % P

    # Precompute coeff_b: list of (-1)^j * C(b, j) mod P for b=1..N
    coeff_b = [[] for _ in range(N+1)]
    for b in range(1, N+1):
        coeff_b[b] = [0] * (b+1)
        for j in range(b+1):
            sign = -1 if j % 2 else 1
            coeff_b[b][j] = (sign * binom[b][j]) % P

    # Precompute C(b,2) as integer
    c2 = [0] * (N+1)
    for b in range(1, N+1):
        c2[b] = b * (b - 1) // 2

    # DP state: (v, e, a, p) -> polynomial in basis of (1+x)^d
    dp = {}
    states_by_v = defaultdict(list)

    # Initial state: layer 0 with vertex 1
    initial_state = (1, 1, 1, 0)
    dp[initial_state] = [1] + [0] * max_deg
    states_by_v[1].append(initial_state)

    for v in range(1, N):
        for state in states_by_v[v]:
            v_cur, e_cur, a_cur, p_cur = state
            c_cur = dp[state]
            for b in range(1, N - v + 1):
                v_new = v + b
                if p_cur == 0:
                    p_new = 1
                    e_new = e_cur
                else:
                    p_new = 0
                    e_new = e_cur + b

                rem = N - v_new
                if rem == 0:
                    if e_new != half:
                        continue
                else:
                    if p_new == 0:
                        min_even = e_new
                        max_even = e_new + rem - 1
                    else:
                        min_even = e_new + 1
                        max_even = e_new + rem
                    if not (min_even <= half <= max_even):
                        continue

                # Compute new polynomial
                new_c = [0] * poly_len
                factor = binom[N - v][b]  # C(N-v, b) mod P
                base = a_cur * b + c2[b]
                coeff_list = coeff_b[b]
                for d in range(poly_len):
                    val = c_cur[d]
                    if val == 0:
                        continue
                    val = (val * factor) % P
                    for j in range(b + 1):
                        nd = d + base - a_cur * j
                        if nd < 0 or nd >= poly_len:
                            continue
                        new_c[nd] = (new_c[nd] + val * coeff_list[j]) % P

                new_state = (v_new, e_new, b, p_new)
                if new_state in dp:
                    existing = dp[new_state]
                    for d in range(poly_len):
                        existing[d] = (existing[d] + new_c[d]) % P
                else:
                    dp[new_state] = new_c
                    states_by_v[v_new].append(new_state)

    # Collect final polynomials for v=N, e=half
    ans_basis = [0] * poly_len
    for state, poly in dp.items():
        v, e, a, p = state
        if v == N and e == half:
            for d in range(poly_len):
                ans_basis[d] = (ans_basis[d] + poly[d]) % P

    # Convert from basis of (1+x)^d to standard coefficients
    ans_std = [0] * poly_len
    for d in range(poly_len):
        cd = ans_basis[d]
        if cd == 0:
            continue
        for i in range(d + 1):
            ans_std[i] = (ans_std[i] + cd * binom[d][i]) % P

    # Output results for M = N-1, ..., max_deg
    result = ans_std[N-1: max_deg+1]
    print(' '.join(map(str, result)))

