import sys

def mat_mul(A, B, mod):
    N = len(A)
    C = [[0] * N for _ in range(N)]
    for i in range(N):
        Ai = A[i]
        Ci = C[i]
        for k in range(N):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(N):
                    Ci[j] = (Ci[j] + aik * Bk[j]) % mod
    return C

def mat_pow(A, exp, mod):
    N = len(A)
    # identity matrix
    R = [[0] * N for _ in range(N)]
    for i in range(N):
        R[i][i] = 1
    base = A
    while exp > 0:
        if exp & 1:
            R = mat_mul(R, base, mod)
        base = mat_mul(base, base, mod)
        exp >>= 1
    return R

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    p = int(next(it))
    A = [[int(next(it)) for _ in range(N)] for _ in range(N)]

    # count zeros
    K = 0
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                K += 1

    if p == 2:
        # replace zeros with 1
        B = [[A[i][j] if A[i][j] != 0 else 1 for j in range(N)] for i in range(N)]
        # compute B^2 mod 2
        res = mat_pow(B, 2, 2)
        out_lines = []
        for i in range(N):
            out_lines.append(' '.join(str(x) for x in res[i]))
        sys.stdout.write('\n'.join(out_lines))
        return

    # p is odd prime
    factor = pow(p - 1, K, p)  # (p-1)^K mod p
    P = mat_pow(A, p, p)  # A^p mod p

    # build C
    C = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if A[i][j] != 0:
                continue
            if i == j:
                # diagonal zero
                # contributions from column i (fixed entries with column i, row != i)
                for s in range(N):
                    if s != i and A[s][i] != 0:
                        C[s][i] = (C[s][i] + A[s][i]) % p
                # contributions from row i (fixed entries with row i, col != i)
                for t in range(N):
                    if t != i and A[i][t] != 0:
                        C[i][t] = (C[i][t] + A[i][t]) % p
            else:
                # off-diagonal zero
                if p == 3:
                    # need A[j][i] (the reverse edge)
                    if A[j][i] != 0:
                        C[i][j] = (C[i][j] + A[j][i]) % p
                # for p > 3 no contribution

    # S = (P + C) mod p
    S = [[(P[i][j] + C[i][j]) % p for j in range(N)] for i in range(N)]

    # result = factor * S mod p
    res = [[(factor * S[i][j]) % p for j in range(N)] for i in range(N)]

    out_lines = []
    for i in range(N):
        out_lines.append(' '.join(str(x) for x in res[i]))
    sys.stdout.write('\n'.join(out_lines))

