class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n == 1:
            return 1
        a = [ord(ch) - 48 for ch in s]

        def min_flips(L: int) -> int:
            if L >= n:
                return 0
            INF = 10 ** 9
            # dp[v][l] : minimal flips for processed prefix,
            #            last value = v (0/1), current run length = l (1..L)
            dp = [[INF] * (L + 1) for _ in range(2)]
            # initialize with the first character
            for v in (0, 1):
                dp[v][1] = 0 if a[0] == v else 1

            for i in range(1, n):
                ndp = [[INF] * (L + 1) for _ in range(2)]
                for v in (0, 1):
                    for l in range(1, L + 1):
                        cur = dp[v][l]
                        if cur == INF:
                            continue
                        # continue the same run
                        if l + 1 <= L:
                            cost = 0 if a[i] == v else 1
                            val = cur + cost
                            if val < ndp[v][l + 1]:
                                ndp[v][l + 1] = val
                        # start a new run with opposite value
                        opp = 1 - v
                        cost = 0 if a[i] == opp else 1
                        val = cur + cost
                        if val < ndp[opp][1]:
                            ndp[opp][1] = val
                dp = ndp

            best = INF
            for v in (0, 1):
                for l in range(1, L + 1):
                    if dp[v][l] < best:
                        best = dp[v][l]
            return best

        lo, hi = 1, n
        answer = n
        while lo <= hi:
            mid = (lo + hi) // 2
            if min_flips(mid) <= numOps:
                answer = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return answer

import sys

def solve():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    # Prefix sums
    P = [0] * (N + 1)
    for i in range(N):
        P[i+1] = P[i] + A[i]
    total_sum = P[N]
    global_max = max(A)

    # Build segment tree for range maximum queries
    n = 1
    while n < N:
        n <<= 1
    tree = [0] * (2 * n)
    for i in range(N):
        tree[n + i] = A[i]
    for i in range(n - 1, 0, -1):
        tree[i] = max(tree[2*i], tree[2*i+1])

    # Find the smallest index i in [l, r] (0-indexed) with A[i] >= threshold
    def find_first(l, r, threshold):
        if l > r:
            return -1
        stack = [(1, 0, n - 1)]
        while stack:
            node, nl, nr = stack.pop()
            if nr < l or nl > r or tree[node] < threshold:
                continue
            if nl == nr:
                return nl
            mid = (nl + nr) // 2
            # Push right child first so that left child is processed first
            stack.append((node*2+1, mid+1, nr))
            stack.append((node*2, nl, mid))
        return -1

    # Find the largest index i in [l, r] (0-indexed) with A[i] >= threshold
    def find_last(l, r, threshold):
        if l > r:
            return -1
        def query(node, nl, nr):
            if ql > nr or qr < nl or tree[node] < threshold:
                return -1
            if nl == nr:
                return nl
            mid = (nl + nr) // 2
            # Try right child first to get the rightmost index
            right_res = query(node*2+1, mid+1, nr)
            if right_res != -1:
                return right_res
            # Then try left child
            return query(node*2, nl, mid)
        ql, qr = l, r
        return query(1, 0, n-1)

    B = [0] * N
    for K in range(N):
        L = R = K
        S = A[K]
        while True:
            expanded = False
            # Try to expand left
            if L > 0:
                left_barrier = find_last(0, L-1, S)
                if left_barrier == -1:
                    newL = 0
                else:
                    newL = left_barrier + 1
                if newL < L:
                    S += P[L] - P[newL]
                    L = newL
                    expanded = True
                    if S > global_max:
                        S = total_sum
                        L = 0
                        R = N - 1
                        break
            # Try to expand right
            if R < N - 1:
                right_barrier = find_first(R+1, N-1, S)
                if right_barrier == -1:
                    newR = N - 1
                else:
                    newR = right_barrier - 1
                if newR > R:
                    S += P[newR+1] - P[R+1]
                    R = newR
                    expanded = True
                    if S > global_max:
                        S = total_sum
                        L = 0
                        R = N - 1
                        break
            if not expanded:
                break
        B[K] = S

    print(' '.join(map(str, B)))

