from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Numbers larger than the threshold can never be part of an edge
        big = [v for v in nums if v > threshold]
        small = [v for v in nums if v <= threshold]
        m = len(small)

        # If there is no number ≤ threshold, every element is isolated
        if m == 0:
            return len(nums)

        # Map each small value to its index in the DSU
        idx = {v: i for i, v in enumerate(small)}
        parent = list(range(m))
        rank = [0] * m

        def find(x: int) -> int:
            # Iterative find with path compression
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        # first[L] stores the first DSU index that divides L (if any)
        first = [-1] * (threshold + 1)

        # Process each small value and unite it with the first divisor of each
        # multiple it appears in.
        for v in small:
            i = idx[v]
            for mult in range(v, threshold + 1, v):
                if first[mult] == -1:
                    first[mult] = i
                else:
                    union(i, first[mult])

        # Count distinct components among the small numbers
        comps = len({find(i) for i in range(m)})

        # All large numbers are isolated components
        comps += len(big)

        return comps
